mapper.insert:
   INSERT INTO custom_requirement_attachment(id,requirement_id,requirement_item_id,attachment_type,storage_key,file_name,material_id,sort_no,created_at)
SELECT #{id},requirement_id,#{item},attachment_type,storage_key,file_name,id,#{sort},#{at} FROM custom_material
WHERE id=#{ref.materialId} AND requirement_id=#{root} AND owner_user_id=#{buyer} AND purpose='requirement' AND (#{retained} OR created_at>DATE_SUB(CAST(#{at} AS DATETIME(3)), INTERVAL 24 HOUR)) AND file_name=#{ref.name} AND attachment_type=#{ref.type}

mapper.update:
   UPDATE custom_requirement SET requirement_status=#{state},version=version+1,updated_at=#{at},
latest_reason=COALESCE(#{reason},latest_reason), submitted_at=IF(#{state}='submitted',#{at},submitted_at),
response_deadline_at=IF(#{state}='submitted',DATE_ADD(CAST(#{at} AS DATETIME(3)),INTERVAL 48 HOUR),response_deadline_at) WHERE id=#{id}
